record.field:
deficit_hours = payslip.undertime_cash_deduction_hours if (payslip and hasattr(payslip, 'undertime_cash_deduction_hours')) else 0.0
w = 0.0
if 'contract' in locals() and contract and hasattr(contract, 'wage'):
    w = contract.wage
elif 'employee' in locals() and employee and hasattr(employee, 'wage'):
    w = employee.wage
elif payslip and hasattr(payslip, 'employee_id') and payslip.employee_id and hasattr(payslip.employee_id, 'wage'):
    w = payslip.employee_id.wage

hourly_rate = w / 240.0
result = -(deficit_hours * hourly_rate)
